SELECT ttl_data_retention_events.plan AS `plan`, COUNT(ttl_data_retention_events.event_id) AS `events`, COUNT(if((ttl_data_retention_events.path != ''), ttl_data_retention_events.event_id, NULL)) AS `eventsWithPath`, MIN(ttl_data_retention_events.occurred_at) AS `oldestEvent`, MAX(ttl_data_retention_events.occurred_at) AS `newestEvent` FROM ttl_data_retention_events GROUP BY `plan` ORDER BY `plan` ASC
